result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/fuzzy/src/score.ts", "content": "/**
 * Fuzzy substring scorer in the spirit of fzy/fzf.
 *
 * A match requires every needle character to appear in the haystack in order
 * (subsequence match, case-insensitive). Among all valid alignments we pick
 * the highest-scoring one via dynamic programming (same recurrence family as
 * fzy):
 *
 *   matchScore[i][j] = max(
 *     matchScore[i][j-1] + GAP_SCORE,   // extend chain across a gap
 *     bestScore[i-1][j-1]               // start fresh after any earlier match
 *   ) + charScore(i, j)
 *
 *   bestScore[i][j] = max(bestScore[i][j-1], matchScore[i][j])
 *
 * charScore rewards:
 *   - any matched character          (+BASE_MATCH)
 *   - word-boundary starts           (+BONUS_BOUNDARY): start of string,
 *     right after a separator (space, '-', '_', '/'), or a camelCase hump
 *   - consecutive matches            (+BONUS_CONSECUTIVE)
 *   - exact-case match               (+BONUS_EXACT_CASE)
 * and the GAP_SCORE term charges every skipped haystack column on the chained
 * path, penalizing sparse alignments.
 */

export interface FuzzyResult {
  score: number;
  /** Haystack indices where needle characters matched, ascending. */
  positions: number[];
}

export const SCORE_MIN = Number.NEGATIVE_INFINITY;

/** Every matched character contributes this baseline. */
export const BASE_MATCH = 4;
/** Match at start-of-string, after a separator, or at a camelCase hump. */
export const BONUS_BOUNDARY = 12;
/** Match immediately following the previous needle character's match. */
export const BONUS_CONSECUTIVE = 8;
/** Small bonus when the character matches with identical case. */
export const BONUS_EXACT_CASE = 2;
/** Penalty charged per skipped haystack column along a match chain. */
export const GAP_SCORE = -3;

const SEPARATORS = new Set([' ', '-', '_', '/']);

function isBoundary(haystack: string, j: number): boolean {
  if (j === 0) return true;
  const prev = haystack[j - 1];
  if (SEPARATORS.has(prev)) return true;
  // camelCase hump: current char uppercase, previous lowercase
  return (
    haystack[j] !== haystack[j].toLowerCase() &&
    prev === prev.toLowerCase() &&
    prev !== prev.toUpperCase()
  );
}

function charScore(
  needleLower: string,
  haystack: string,
  haystackLower: string,
  i: number,
  j: number,
  consecutive: boolean,
): number {
  let score = BASE_MATCH;
  if (consecutive) score += BONUS_CONSECUTIVE;
  if (isBoundary(haystack, j)) score += BONUS_BOUNDARY;
  if (needleLower[i] === haystack[j]) score += BONUS_EXACT_CASE;
  return score;
}

/**
 * Match `needle` inside `haystack`.
 * Returns null when needle characters cannot be matched in order,
 * otherwise the best alignment's score and matched positions.
 */
export function fuzzyMatch(needle: string, haystack: string): FuzzyResult | null {
  if (needle.length === 0) return { score: 0, positions: [] };
  if (haystack.length < needle.length) return null;

  const n = needle.length;
  const m = haystack.length;
  const needleLower = needle.toLowerCase();
  const haystackLower = haystack.toLowerCase();

  // Quick subsequence check.
  let k = 0;
  for (let j = 0; j < m && k < n; j++) {
    if (haystackLower[j] === needleLower[k]) k++;
  }
  if (k < n) return null;

  const NEG = SCORE_MIN;
  // bestScore[i][j]: best score matching needle[0..i] using haystack[0..j].
  const bestScore: number[][] = [];
  // matchScore[i][j]: best score matching needle[0..i] with needle[i]
  // matched exactly at haystack[j].
  const matchScore: number[][] = [];
  // pred[i][j]: haystack index of needle[i-1]'s match for the optimal
  // alignment ending with needle[i] at j (-1 when i === 0).
  const pred: number[][] = [];
  // argBest[i][j]: j' achieving bestScore[i][j].
  const argBest: number[][] = [];

  for (let i = 0; i < n; i++) {
    bestScore[i] = new Array<number>(m).fill(NEG);
    matchScore[i] = new Array<number>(m).fill(NEG);
    pred[i] = new Array<number>(m).fill(-1);
    argBest[i] = new Array<number>(m).fill(-1);
    let runningBest = NEG;
    let runningArg = -1;
    for (let j = 0; j < m; j++) {
      if (haystackLower[j] === needleLower[i]) {
        const chained = i > 0 && j > 0 ? matchScore[i - 1][j - 1] + GAP_SCORE : NEG;
        const restart = i > 0 && j > 0 ? bestScore[i - 1][j - 1] : i === 0 ? 0 : NEG;
        const consecutive = i > 0 && j > 0 && matchScore[i - 1][j - 1] > NEG && chained >= restart;
        const bonus = charScore(needleLower, haystack, haystackLower, i, j, consecutive);
        const score = Math.max(chained, restart) + bonus;
        if (score > matchScore[i][j]) {
          matchScore[i][j] = score;
          pred[i][j] = chained >= restart
            ? (i > 0 && j > 0 ? argBest[i - 1][j - 1] : -1)
            : (i > 0 && j > 0 ? argBest[i - 1][j - 1] : -1);
        }
      }
      if (matchScore[i][j] > runningBest) {
        runningBest = matchScore[i][j];
        runningArg = j;
      }
      bestScore[i][j] = runningBest;
      argBest[i][j] = runningArg;
    }
  }

  const endJ = argBest[n - 1][m - 1];
  if (endJ < 0 || !Number.isFinite(matchScore[n - 1][endJ])) return null;

  const positions = new Array<number>(n);
  let j = endJ;
  for (let i = n - 1; i >= 0; i--) {
    positions[i] = j;
    j = i > 0 ? pred[i][j] : -1;
  }

  return { score: matchScore[n - 1][endJ], positions };
}

export interface RankedCandidate<T = string> {
  candidate: T;
  score: number;
  positions: number[];
}

/**
 * Rank `candidates` against `needle`, dropping non-matches.
 * Ordering: score descending, then shorter candidate first, then
 * alphabetically ascending. Returns at most `limit` results.
 */
export function search<T extends string>(
  needle: string,
  candidates: readonly T[],
  limit: number = Infinity,
): RankedCandidate<T>[] {
  const ranked: RankedCandidate<T>[] = [];
  for (const candidate of candidates) {
    const result = fuzzyMatch(needle, candidate);
    if (result) {
      ranked.push({ candidate, score: result.score, positions: result.positions });
    }
  }
  ranked.sort((a, b) => {
    if (b.score !== a.score) return b.score - a.score;
    if (a.candidate.length !== b.candidate.length) return a.candidate.length - b.candidate.length;
    return a.candidate.localeCompare(b.candidate);
  });
  return limit === Infinity ? ranked : ranked.slice(0, limit);
}
