result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/fuzzy/test/score.test.ts", "content": "import { describe, it, expect } from 'vitest';
import {
  fuzzyMatch,
  search,
  BASE_MATCH,
  BONUS_BOUNDARY,
  BONUS_CONSECUTIVE,
  BONUS_EXACT_CASE,
} from '../src/score';

describe('fuzzyMatch', () => {
  it('returns null when characters cannot be matched in order', () => {
    expect(fuzzyMatch('zx', 'abc')).toBeNull();
    expect(fuzzyMatch('ab', 'ba')).toBeNull(); // order matters
    expect(fuzzyMatch('abc', 'ab')).toBeNull(); // needle longer than haystack
    expect(fuzzyMatch('xyz', '')).toBeNull();
  });

  it('matches case-insensitively', () => {
    expect(fuzzyMatch('ABC', 'abc')).not.toBeNull();
    expect(fuzzyMatch('abc', 'ABC')).not.toBeNull();
  });

  it('empty needle matches trivially with zero score', () => {
    expect(fuzzyMatch('', 'anything')).toEqual({ score: 0, positions: [] });
  });

  it('positions: gc in garbage-collector -> [0, 8] (start + after separator)', () => {
    // 'g' at index 0 (boundary), 'c' at index 8 right after '-'.
    expect(fuzzyMatch('gc', 'garbage-collector')).toEqual({
      score: (BASE_MATCH + BONUS_BOUNDARY) * 2,
      positions: [0, 8],
    });
  });

  it('positions: abc in a-b-c -> [0, 2, 4] (every match is a boundary)', () => {
    const r = fuzzyMatch('abc', 'a-b-c')!;
    expect(r.positions).toEqual([0, 2, 4]);
    expect(r.score).toBe((BASE_MATCH + BONUS_BOUNDARY) * 3);
  });

  it('prefers consecutive matches over spread-out ones at equal boundaries', () => {
    // 'hello' fully consecutive beats 'h-e-l-l-o' where each char is a
    // separated boundary but no two matches are adjacent... boundary bonus is
    // large, so compare against an alignment that has neither boundaries nor
    // consecutiveness instead.
    const tight = fuzzyMatch('ell', 'hello')!;
    // e,l,l at indices 1,2,3: one boundary-free start plus two consecutive.
    expect(tight.positions).toEqual([1, 2, 3]);
    const loose = fuzzyMatch('el', 'hexlx')!;
    // e at 1, l at 3: no boundary, no consecutive.
    expect(loose.positions).toEqual([1, 3]);
    expect(tight.score).toBeGreaterThan(loose.score);
  });

  it('rewards camelCase humps as word boundaries', () => {
    const r = fuzzyMatch('gc', 'GraphicsCard')!;
    expect(r.positions).toEqual([0, 8]); // 'G' start, 'C' hump of "Card"
    expect(r.score).toBe((BASE_MATCH + BONUS_BOUNDARY) * 2);
  });

  it('gives a small bonus for exact-case matches', () => {
    const exact = fuzzyMatch('gc', 'gc')!;
    const shifted = fuzzyMatch('GC', 'gc')!;
    expect(exact.score).toBe(shifted.score + 2 * BONUS_EXACT_CASE);
  });

  it('penalizes gaps: same alignment shape scores lower with skipped chars', () => {
    // Both have one boundary-free interior match; 'axxxb' forces a longer gap
    // chain before 'b', which can only be reached through gap columns.
    const short = fuzzyMatch('gb', 'gxbscorex')!; // g@0, b@2
    const long = fuzzyMatch('ge', 'gxxxxxxxex')!; // g@0, e@8
    expect(short.score).toBeGreaterThan(long.score);
  });
});

describe('search ranking', () => {
  const candidates = ['garbage-collector', 'GraphicsCard', 'logic', 'grep-count'];

  it('pins the exact ordering for needle "gc"', () => {
    // Scoring breakdown:
    //   grep-count         36  (g@0 boundary=16, c@5 after '-'=20)
    //   garbage-collector  36  (g@0 boundary=16, c@8 after '-'=20)
    //   GraphicsCard       32  (G@0 hump/start=16, C@8 camelCase hump=16)
    //   logic              12  (g@2 mid-word=4, c@4 mid-word=4, minus gaps)
    // grep-count ties garbage-collector at 36 and wins the tiebreak by being
    // shorter (10 vs 17 chars). logic matches only mid-word and trails.
    const ranked = search('gc', candidates).map((r) => r.candidate);
    expect(ranked).toEqual(['grep-count', 'garbage-collector', 'GraphicsCard', 'logic']);
  });

  it('ties on score are broken by shorter candidate, then alphabetically', () => {
    // All of fo/fob/foo score identically ('o' mid-word); odo scores higher
    // because both 'o's sit at boundaries relative to its layout.
    expect(search('o', ['foo', 'fo', 'fob', 'odo']).map((r) => r.candidate)).toEqual([
      'odo',
      'fo',
      'fob',
      'foo',
    ]);
  });

  it('drops non-matching candidates', () => {
    expect(search('zz', candidates)).toEqual([]);
  });

  it('respects the limit after sorting', () => {
    const top = search('gc', candidates, 2);
    expect(top.map((r) => r.candidate)).toEqual(['grep-count', 'garbage-collector']);
  });

  it('exposes positions alongside the ranking', () => {
    expect(search('gc', ['GraphicsCard'])[0].positions).toEqual([0, 8]);
  });
});
"})
