result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/fuzzy/test/score.test.ts", "content": "import { describe, it, expect } from 'vitest';
import {
  fuzzyMatch,
  search,
  BASE_MATCH,
  BONUS_BOUNDARY,
  BONUS_CONSECUTIVE,
  BONUS_EXACT_CASE,
  GAP_SCORE,
} from '../src/score';

const START_HIT = BASE_MATCH + BONUS_BOUNDARY + BONUS_EXACT_CASE; // 18

describe('fuzzyMatch', () => {
  it('returns null when characters cannot be matched in order', () => {
    expect(fuzzyMatch('zx', 'abc')).toBeNull();
    expect(fuzzyMatch('ab', 'ba')).toBeNull(); // order matters
    expect(fuzzyMatch('abc', 'ab')).toBeNull(); // needle longer than haystack
    expect(fuzzyMatch('xyz', '')).toBeNull();
  });

  it('matches case-insensitively', () => {
    expect(fuzzyMatch('ABC', 'abc')).not.toBeNull();
    expect(fuzzyMatch('abc', 'ABC')).not.toBeNull();
  });

  it('empty needle matches trivially with zero score', () => {
    expect(fuzzyMatch('', 'anything')).toEqual({ score: 0, positions: [] });
  });

  it('positions: gc in garbage-collector -> [0, 8] (start + after separator)', () => {
    // 'g' at index 0 (start-of-string): 18 points.
    // 'c' at index 8 (after '-'): 18 points, reached through 7 gap columns
    // that decay the carried score by GAP_SCORE each -> 18 + 7*GAP_SCORE.
    const r = fuzzyMatch('gc', 'garbage-collector')!;
    expect(r.positions).toEqual([0, 8]);
    expect(r.score).toBe(START_HIT + (START_HIT + 7 * GAP_SCORE)); // 15
  });

  it('positions: abc in a-b-c -> [0, 2, 4] (every match is a boundary)', () => {
    // Each char sits right after a separator: three boundary hits chained by
    // two single-column gaps (one per skipped '-' column).
    const r = fuzzyMatch('abc', 'a-b-c')!;
    expect(r.positions).toEqual([0, 2, 4]);
    expect(r.score).toBe(48);
  });

  it('prefers consecutive matches over spread-out ones of the same shape', () => {
    // 'ell' in hello: e,l,l adjacent -> consecutive bonuses chain up.
    const tight = fuzzyMatch('ell', 'hello')!;
    expect(tight.positions).toEqual([1, 2, 3]);
    // 'el' in hexlx: no boundary, no consecutiveness, plus gap decay.
    const loose = fuzzyMatch('el', 'hexlx')!;
    expect(loose.positions).toEqual([1, 3]);
    expect(tight.score).toBe(47); // includes 2 * BONUS_CONSECUTIVE
    expect(tight.score).toBeGreaterThan(loose.score);
  });

  it('rewards camelCase humps as word boundaries', () => {
    // 'G' at start (no exact-case bonus), 'C' at the "Card" hump.
    expect(fuzzyMatch('gc', 'GraphicsCard')).toEqual({
      score: 11, // (4 + BOUNDARY) + ((4 + BOUNDARY) + 7 * GAP)
      positions: [0, 8],
    });
  });

  it('gives a small bonus for exact-case matches', () => {
    const exact = fuzzyMatch('gc', 'gc')!;
    const shifted = fuzzyMatch('GC', 'gc')!;
    expect(exact.score).toBe(40); // both chars match with identical case
    expect(shifted.score).toBe(36);
    expect(exact.score).toBe(shifted.score + 2 * BONUS_EXACT_CASE);
  });

  it('penalizes gaps: longer gaps score strictly less', () => {
    // Same alignment shape (boundary start + plain interior match); only the
    // gap length differs, and the carried score decays per skipped column.
    const shortGap = fuzzyMatch('gb', 'gxbscorex')!; // gap of 1 column
    const longGap = fuzzyMatch('ge', 'gxxxxxxxex')!; // gap of 7 columns
    expect(shortGap.positions).toEqual([0, 2]);
    expect(longGap.positions).toEqual([0, 8]);
    expect(shortGap.score).toBe(START_HIT + (BASE_MATCH + GAP_SCORE)); // 19
    expect(shortGap.score).toBeGreaterThan(longGap.score);
  });
});

describe('search ranking', () => {
  const candidates = ['garbage-collector', 'GraphicsCard', 'logic', 'grep-count'];

  it('pins the exact ordering for needle "gc"', () => {
    // Scoring breakdown:
    //   grep-count         24  g@0 boundary+exact=18, c@5 after '-' through
    //                          4 gap columns (18 - 4*GAP) + boundary hit = 24
    //   garbage-collector  15  g@0 = 18, c@8 after '-' but 7 gap columns
    //                          erode the carry: 18 - 7*GAP + 18 = 15
    //   GraphicsCard       11  G@0 hump/start=16 (no exact-case), C@8 hump
    //                          after 7 gap columns: 16 - 7*GAP + 16 = 11
    //   logic               3  g@2 pays a leading gap penalty, c@4 mid-word;
    //                          everything decays to 3
    // All four scores are distinct, so ordering is decided purely by score.
    const ranked = search('gc', candidates);
    expect(ranked.map((r) => r.candidate)).toEqual([
      'grep-count',
      'garbage-collector',
      'GraphicsCard',
      'logic',
    ]);
    expect(ranked.map((r) => r.score)).toEqual([24, 15, 11, 3]);
    expect(ranked[0].positions).toEqual([0, 5]);
    expect(ranked[1].positions).toEqual([0, 8]);
    expect(ranked[2].positions).toEqual([0, 8]);
    expect(ranked[3].positions).toEqual([2, 4]);
  });

  it('ties on score are broken by shorter candidate, then alphabetically', () => {
    // With the single-char needle every 'o' in fo/fob/foo is a mid-word match
    // worth exactly 3 (leading gap penalty included), so they tie; odo's 'o'
    // at index 0 is a start-of-string hit worth 18 and wins outright.
    expect(search('o', ['foo', 'fo', 'fob', 'odo']).map((r) => r.candidate)).toEqual([
      'odo',
      'fo',
      'fob',
      'foo',
    ]);
  });

  it('drops non-matching candidates', () => {
    expect(search('zz', candidates)).toEqual([]);
  });

  it('respects the limit after sorting', () => {
    expect(search('gc', candidates, 2).map((r) => r.candidate)).toEqual([
      'grep-count',
      'garbage-collector',
    ]);
  });
});
